import{_ as i,o as t,c as a,ae as l}from"./chunks/framework.CK6jtcgr.js";const p=JSON.parse('{"title":"Public vs Restricted Security Boundary","description":"","frontmatter":{},"headers":[],"relativePath":"guide/public-vs-restricted-security-boundary.md","filePath":"guide/public-vs-restricted-security-boundary.md"}'),r={name:"guide/public-vs-restricted-security-boundary.md"};function o(n,e,s,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="public-vs-restricted-security-boundary" tabindex="-1">Public vs Restricted Security Boundary <a class="header-anchor" href="#public-vs-restricted-security-boundary" aria-label="Permalink to &quot;Public vs Restricted Security Boundary&quot;">​</a></h1><p>This page is the public manual entry point for SocioProphet&#39;s disclosure boundary.</p><p>SocioProphet is explicit about what belongs in the public architecture layer and what remains restricted. That is not a contradiction and not a hedge. It is part of the system design.</p><h2 id="_1-why-this-boundary-exists" tabindex="-1">1. Why this boundary exists <a class="header-anchor" href="#_1-why-this-boundary-exists" aria-label="Permalink to &quot;1. Why this boundary exists&quot;">​</a></h2><p>A serious system must be legible without becoming a misuse amplifier.</p><p>That means the public layer must provide:</p><ul><li>clarity</li><li>governance legibility</li><li>architectural honesty</li><li>safety-boundary explanation</li><li>institutional confidence</li><li>evidence that the platform is bounded and reviewable</li></ul><p>At the same time, the public layer must not disclose tactical detail that materially increases misuse value.</p><p>This boundary is therefore part of the platform&#39;s safety architecture.</p><h2 id="_2-what-we-publish-publicly" tabindex="-1">2. What we publish publicly <a class="header-anchor" href="#_2-what-we-publish-publicly" aria-label="Permalink to &quot;2. What we publish publicly&quot;">​</a></h2><p>The public layer includes:</p><ul><li>product architecture</li><li>governance model</li><li>bounded-execution model</li><li>deterministic AI thesis</li><li>operator role model</li><li>workflow states</li><li>evidence and provenance model</li><li>institutional deployment framing</li><li>public-safe defensive posture</li><li>public-safe analytics and boundary model</li><li>reversibility and promotion logic at the architectural level</li></ul><p>This gives institutions, operators, researchers, and stakeholders enough information to understand the system honestly.</p><h2 id="_3-what-remains-restricted" tabindex="-1">3. What remains restricted <a class="header-anchor" href="#_3-what-remains-restricted" aria-label="Permalink to &quot;3. What remains restricted&quot;">​</a></h2><p>Restricted material includes:</p><ul><li>sensitive operator kits</li><li>exact tactical playbooks</li><li>exploit or persistence workflows</li><li>high-fidelity adversary-emulation mechanics</li><li>evasion-sensitive logic</li><li>restricted thresholds</li><li>privileged deployment internals</li><li>misuse-enabling tradecraft</li><li>other details that materially increase misuse value</li></ul><p>We do not publish those details merely to sound advanced.</p><h2 id="_4-what-this-means-in-practice" tabindex="-1">4. What this means in practice <a class="header-anchor" href="#_4-what-this-means-in-practice" aria-label="Permalink to &quot;4. What this means in practice&quot;">​</a></h2><p>In practice, the public layer explains:</p><ul><li>what the system does</li><li>how it is governed</li><li>how work moves through it</li><li>how analytics, workflows, and validation connect</li><li>how promotions and reversals work</li><li>where the authorization boundary sits</li><li>why some implementation detail is intentionally withheld</li></ul><p>The restricted layer contains the tactical and operational material that would make the public docs unsafe or irresponsible if published in full.</p><h2 id="_5-relationship-to-deterministic-ai" tabindex="-1">5. Relationship to deterministic AI <a class="header-anchor" href="#_5-relationship-to-deterministic-ai" aria-label="Permalink to &quot;5. Relationship to deterministic AI&quot;">​</a></h2><p>The public-vs-restricted boundary is tied directly to the deterministic AI thesis.</p><p>A deterministic and bounded system is not only about execution. It is also about disclosure discipline.</p><p>If the public layer published every sensitive tactical internal, the platform would be violating its own safety claims.</p><p>Relevant references:</p><ul><li><a href="https://socioprophet.com/documentation/deterministic-ai-and-mathematical-safety/" target="_blank" rel="noreferrer">Deterministic AI and Mathematical Safety</a></li><li><a href="https://socioprophet.com/documentation/governed-ai-and-cybernetics/" target="_blank" rel="noreferrer">Governed AI and Cybernetics</a></li></ul><h2 id="_6-relationship-to-organizations" tabindex="-1">6. Relationship to organizations <a class="header-anchor" href="#_6-relationship-to-organizations" aria-label="Permalink to &quot;6. Relationship to organizations&quot;">​</a></h2><p>Institutions need to know not only that the system is governed, but that the documentation boundary itself is governed.</p><p>This matters because institutional adoption depends on:</p><ul><li>clear governance</li><li>clear authorization</li><li>clear evidence model</li><li>clear disclosure discipline</li><li>confidence that public explanation does not collapse into irresponsible release of tactical detail</li></ul><p>Relevant reference:</p><ul><li><a href="https://socioprophet.com/documentation/organizations-governance-and-institutional-safety/" target="_blank" rel="noreferrer">Organizations Governance and Institutional Safety</a></li></ul><h2 id="_7-relationship-to-defense-and-validation" tabindex="-1">7. Relationship to defense and validation <a class="header-anchor" href="#_7-relationship-to-defense-and-validation" aria-label="Permalink to &quot;7. Relationship to defense and validation&quot;">​</a></h2><p>Authorized Cyberdefense and Simulation is the clearest example of this boundary in action.</p><p>The public layer can explain:</p><ul><li>authorization boundary</li><li>defense-first posture</li><li>evidence-bearing validation</li><li>remediation logic</li><li>governance and review</li></ul><p>The public layer does not need to publish:</p><ul><li>restricted simulation internals</li><li>tactical adversary tradecraft</li><li>exact playbooks</li><li>restricted thresholds</li></ul><p>Relevant reference:</p><ul><li><a href="https://socioprophet.com/documentation/authorized-cyberdefense-and-simulation/" target="_blank" rel="noreferrer">Authorized Cyberdefense and Simulation</a></li></ul><h2 id="_8-relationship-to-the-boundary-first-model" tabindex="-1">8. Relationship to the boundary-first model <a class="header-anchor" href="#_8-relationship-to-the-boundary-first-model" aria-label="Permalink to &quot;8. Relationship to the boundary-first model&quot;">​</a></h2><p>The Boundary-Centric Cyber Hypergraph helps explain this documentation boundary.</p><p>The public docs can explain the model of:</p><ul><li>component</li><li>port</li><li>contract</li><li>boundary event</li><li>evidence</li><li>expectation</li><li>finding</li></ul><p>without publishing every restricted data source, tactic, or internal operator mechanic.</p><p>Relevant reference:</p><ul><li><a href="https://socioprophet.com/documentation/boundary-centric-cyber-hypergraph/" target="_blank" rel="noreferrer">Boundary-Centric Cyber Hypergraph</a></li></ul><h2 id="_9-why-this-matters" tabindex="-1">9. Why this matters <a class="header-anchor" href="#_9-why-this-matters" aria-label="Permalink to &quot;9. Why this matters&quot;">​</a></h2><p>Without an explicit public-vs-restricted boundary, one of two bad things usually happens.</p><p>Either:</p><ul><li>the public layer becomes vague and untrustworthy</li></ul><p>or:</p><ul><li>the public layer becomes recklessly over-disclosive</li></ul><p>SocioProphet rejects both.</p><p>The system is designed to be:</p><ul><li>honest</li><li>legible</li><li>reviewable</li><li>bounded</li><li>explicit about what remains outside the public layer</li></ul><h2 id="_10-use-this-page" tabindex="-1">10. Use this page <a class="header-anchor" href="#_10-use-this-page" aria-label="Permalink to &quot;10. Use this page&quot;">​</a></h2><p>Use this page when the question is:</p><ul><li>Why are some details public and others restricted?</li><li>Where is the disclosure boundary?</li><li>How does the documentation boundary connect to the platform&#39;s safety claims?</li><li>How do deterministic AI, institutional governance, and authorized validation reinforce this line?</li></ul>',60)])])}const b=i(r,[["render",o]]);export{p as __pageData,b as default};
